<?php $ci =& get_instance();$project=$garden_project;$editable=$ci->permissions('service_jobs_edit') && !in_array($project->stage,['closed','cancelled'],true);$labels=mp_garden_project_stages();$stages=array_keys($labels);$current=array_search($project->stage,$stages,true);$inspection=json_decode($project->inspection_json ?? '',true) ?: [];$jobId=(int)$project->job_id;$linkedQuote=null;foreach ($garden_quotes as $candidate) if ((int)$candidate->id===(int)$project->quotation_id) $linkedQuote=$candidate; ?>
<div class="garden-project-heading"><div><a href="<?= base_url('garden/projects'); ?>">← Project board</a><h2><?= htmlspecialchars($project->customer_name); ?></h2><p><?= nl2br(htmlspecialchars($project->description ?? '')); ?></p></div><span class="garden-pill"><?= htmlspecialchars($labels[$project->stage] ?? $project->stage); ?></span></div>
<nav class="garden-project-tabs" aria-label="Inside this project"><a href="#project-workflow">Workflow</a><a href="#project-site">Site records</a><a href="#project-tasks">Team tasks</a><a href="#project-documents">Documents & costs</a><a href="#project-history">History</a></nav>
<section class="garden-panel" id="project-workflow"><div class="garden-panel-heading"><div><span class="garden-kicker">THE PROJECT JOURNEY</span><h2>Workflow</h2></div></div>
<div class="garden-workflow-board"><?php foreach ($labels as $key=>$label): if ($key==='cancelled') continue;$index=array_search($key,$stages,true);$state=$project->stage==='cancelled' ? 'pending' : ($key===$project->stage ? 'current' : ($index<$current ? 'done' : 'pending')); ?><div class="garden-workflow-step is-<?= $state; ?>"><small><?= $state==='done' ? '✓ Complete' : ($state==='current' ? 'Current stage' : 'Upcoming'); ?></small><strong><?= htmlspecialchars($label); ?></strong></div><?php endforeach; ?></div>
<?php if ($editable && $project->stage==='enquiry'): ?><div class="garden-inspection-spotlight"><span class="garden-kicker">START HERE · SITE INSPECTION</span><h3>Assess the site before planning the work</h3><p>Capture conditions, risks, measurements and recommendations in the structured assessment.</p><a class="garden-button" href="#project-site" data-open-assessment>Open site assessment →</a></div><?php endif; ?>
<?php if ($editable): $next=['inspection'=>'quoted','approved'=>'deposit','deposit'=>'execution','execution'=>'completed','completed'=>'paid','paid'=>'closed'][$project->stage] ?? null; ?>
<div class="garden-next-step">
<?php if ($linkedQuote): $this->load->view('garden/quotation_response_action',['response_quote'=>$linkedQuote]); endif; ?>
<?php if ($project->stage==='quoted' && $linkedQuote && $linkedQuote->lifecycle_status==='accepted' && $ci->permissions('quotation_edit')): ?>
<form method="post" action="<?= base_url('garden/advance_project'); ?>"><?php $this->load->view('garden/form_token'); ?><input type="hidden" name="job_id" value="<?= $jobId; ?>"><input type="hidden" name="stage" value="approved"><p>The client has accepted the linked quotation. Confirm to move this project into Approved; the quotation revision is checked again.</p><button class="garden-button">Continue with accepted quotation</button></form>
<?php elseif ($project->stage==='quoted' && $ci->permissions('quotation_edit')): ?>
<form method="post" action="<?= base_url('garden/project_approval'); ?>"><?php $this->load->view('garden/form_token'); ?><input type="hidden" name="job_id" value="<?= $jobId; ?>"><input type="hidden" name="revision" value="<?= (int)$project->quotation_revision; ?>"><h3>Record customer approval</h3><p>Confirm approval for the linked quotation, revision <?= (int)$project->quotation_revision; ?>. This records the response in the quotation history.</p><label>Who approved, when and how?<textarea id="garden-approval-note" name="evidence" rows="2" maxlength="255" required placeholder="e.g. Customer approved revision 1 by signed email on 15 October."></textarea></label><?php $this->load->view('garden/voice_button',['voice_target'=>'garden-approval-note']); ?><label><input type="checkbox" name="approval_confirmed" value="1" required> I have received customer approval for this revision.</label><button class="garden-button">Record approval & continue</button></form>
<?php elseif ($next): ?>
<form method="post" action="<?= base_url('garden/advance_project'); ?>"><?php $this->load->view('garden/form_token'); ?><input type="hidden" name="job_id" value="<?= $jobId; ?>"><input type="hidden" name="stage" value="<?= $next; ?>"><h3>Next: <?= htmlspecialchars($labels[$next]); ?></h3>
<?php if ($next==='inspection'): ?><p>Complete and save the structured site inspection below. Then mark the inspection stage complete.</p><a href="#project-site">Open site inspection ↓</a>
<?php elseif ($next==='quoted'): ?><p>Create a quotation from this project or select an existing quotation for this customer.</p><label>Quotation<select name="quotation_id" data-garden-select hidden required><option value="">Choose quotation</option><?php foreach ($garden_quotes as $quote): ?><option value="<?= (int)$quote->id; ?>" <?= (int)$project->quotation_id===(int)$quote->id ? 'selected' : ''; ?>><?= htmlspecialchars(($quote->quotation_code ?: '#'.$quote->id).' · '.$quote->quotation_date.' · '.store_number_format($quote->grand_total)); ?></option><?php endforeach; ?></select></label>
<?php elseif ($next==='deposit'): ?><p>Convert the approved quotation to an invoice and record the actual deposit on that invoice. The project verifies the payment before advancing.</p><label>Invoice from this quotation<select name="sales_id" data-garden-select hidden><option value="">Use linked invoice</option><?php foreach ($garden_invoices as $invoice): ?><option value="<?= (int)$invoice->id; ?>" <?= (int)$project->sales_id===(int)$invoice->id ? 'selected' : ''; ?>><?= htmlspecialchars(($invoice->sales_code ?: '#'.$invoice->id).' · '.store_number_format($invoice->grand_total).' · '.$invoice->sales_status); ?></option><?php endforeach; ?></select></label>
<?php elseif ($next==='execution'): ?><p>The approved quotation, final invoice and received deposit are checked before work starts.</p>
<?php elseif ($next==='completed'): ?><p>Record customer confirmation and finish the team task cards before marking the work complete.</p>
<?php elseif ($next==='paid'): ?><p>Record the remaining payment on the linked invoice. This step checks the invoice has no outstanding balance.</p>
<?php elseif ($next==='closed'): ?><p>Close the project once the work is signed off and the invoice is settled.</p><?php endif; ?>
<label>Progress / customer confirmation notes<textarea id="garden-stage-note" name="note" rows="2" maxlength="8000" <?= $next==='completed' ? 'required' : ''; ?>></textarea></label><?php $this->load->view('garden/voice_button',['voice_target'=>'garden-stage-note']); ?><button class="garden-button">Confirm <?= htmlspecialchars(strtolower($labels[$next])); ?></button></form>
<?php endif; ?>
<?php if (in_array($project->stage,['enquiry','inspection','quoted','approved','deposit'],true)): ?><details><summary class="garden-disclosure-toggle garden-disclosure-danger">Cancel this project</summary><form method="post" action="<?= base_url('garden/advance_project'); ?>"><?php $this->load->view('garden/form_token'); ?><input type="hidden" name="job_id" value="<?= $jobId; ?>"><input type="hidden" name="stage" value="cancelled"><label>Reason<textarea name="note" rows="2" required></textarea></label><p>Cancellation retains documents, payments and costs. Handle any refund through the existing invoice workflow.</p><button type="submit" class="garden-button garden-button-danger">Cancel project</button></form></details><?php endif; ?>
</div><?php endif; ?></section>
<?php $projectParts=['ci'=>$ci,'project'=>$project,'editable'=>$editable,'jobId'=>$jobId,'inspection'=>$inspection]; ?>
<?php $this->load->view('garden/project_site',$projectParts); ?>
<?php $this->load->view('garden/project_tasks',$projectParts); ?>
<?php $this->load->view('garden/project_documents',$projectParts); ?>
<section class="garden-panel" id="project-history"><div class="garden-panel-heading"><div><span class="garden-kicker">AUDIT TRAIL</span><h2>Project history</h2></div></div><div class="garden-timeline"><?php foreach ($garden_history as $event): ?><article><small><?= htmlspecialchars($event->created_at); ?></small><strong><?= htmlspecialchars($labels[$event->to_stage] ?? $event->to_stage); ?></strong><p><?= nl2br(htmlspecialchars($event->note ?? '')); ?></p></article><?php endforeach; ?></div></section>
